const NET_IPC_RECV int32 = 0xB04
const NET_IPC_CLOSE int32 = 0xB05
const NET_IPC_POLL int32 = 0xB06
const NET_IPC_IFADDR_ADD int32 = 0xB07
const NET_IPC_IFADDR_DEL int32 = 0xB08
const NET_IPC_IFADDR_LIST int32 = 0xB09
// The link-layer address of the interface a packet socket transmits on.
// arg0=interface index (0 selects the first interface that is up).
// On success: NET_IPC_RESP, arg0 = the low four address bytes, arg1 = the
// high two, both in wire order with byte 0 in the low byte.
// A packet socket needs this because the client owns the ethernet header
// and must put a real source address in it, or a reply is addressed to a
// machine that does not exist.
const NET_IPC_IF_HWADDR int32 = 0xB17
const NET_IPC_STACK_CREATE int32 = 0xB0A
const NET_IPC_STACK_DESTROY int32 = 0xB0B
const NET_IPC_STACK_SELECT int32 = 0xB0C
const NET_IPC_DATA_NOTIFY int32 = 0xB0D
const NET_IPC_TX_NOTIFY int32 = 0xB0E
const NET_IPC_RX_NOTIFY int32 = 0xB0F
// Administrative interface up/down: arg0 = if_index, arg1 = 1 up / 0 down.
const NET_IPC_IF_SET_STATE int32 = 0xB10
// DHCP client on/off: arg0 = if_index, arg1 = 1 start / 0 stop. Starting
// clears any static address so the client can bind a fresh lease; stopping
// leaves the current address in place.
const NET_IPC_DHCP_SET int32 = 0xB11
// Passive-open a bound stream socket: arg0 = socket_id. Reply is immediate.
const NET_IPC_LISTEN int32 = 0xB12
// Post rings for the next inbound connection on a listening socket:
// arg0 = listening socket_id, arg1 = descriptor buffer_id,
// arg2 = descriptor borrow_id, arg3 = descriptor bytes. The descriptor
// (net_socket_open_descriptor_v1_t) carries the accepted socket's TX/RX ring
// grants. The reply is deferred until a connection is paired, and its
// arg0 (NET_IPC_RESP) is the accepted socket_id. Each posted ACCEPT is one
// accept slot; post several to accept several connections.
const NET_IPC_ACCEPT int32 = 0xB13
// Resolve a hostname to an IPv4 address. The name is carried in a borrowed
// xfer buffer: arg0 = buffer_id, arg1 = borrow_id, arg2 = name length. The
// reply is deferred until the lwIP DNS callback fires. On RESP, arg0 is the
// status and arg1 is the resolved IPv4 (network-order word); failure comes
// back as NET_IPC_ERROR.
const NET_IPC_RESOLVE int32 = 0xB14
// Replace the resolver list: arg0 = count (0..2), arg1/arg2 = server IPv4
// (network-order words). count=0 clears all servers. Reply is immediate.
const NET_IPC_DNS_SET int32 = 0xB15
// List configured resolvers. On RESP, arg0 is the status, arg1 = count and
// arg2/arg3 = the first two server IPv4 addresses (network-order words).
// Reply is immediate.
const NET_IPC_DNS_LIST int32 = 0xB16
const NET_IPC_RESP int32 = 0xB80
const NET_IPC_ERROR int32 = 0xBFF

// proc_dma (0x230..0x2BF)
const PROC_IPC_DMA_MAP_BORROW_REQ int32 = 0x230
const PROC_IPC_DMA_SYNC_BORROW_REQ int32 = 0x231
const PROC_IPC_DMA_UNMAP_BORROW_REQ int32 = 0x232
const PROC_IPC_DMA_BORROW_RESP int32 = 0x2B0
const PROC_IPC_DMA_BORROW_ERROR int32 = 0x2BF

// font (0xA00..0xAFF)
const FONT_IPC_OPEN_FONT_REQ int32 = 0xA00
const FONT_IPC_GET_METRICS_REQ int32 = 0xA01
const FONT_IPC_MEASURE_GLYPH_REQ int32 = 0xA03
const FONT_IPC_RASTER_GLYPH_INTO_REQ int32 = 0xA04
const FONT_IPC_RESP int32 = 0xA80
const FONT_IPC_ERROR int32 = 0xAFF

// gfx (0x200..0x2FF)
const GFX_IPC_CREATE_WINDOW int32 = 0x200
const GFX_IPC_DESTROY_WINDOW int32 = 0x201
const GFX_IPC_RESIZE_WINDOW int32 = 0x202
const GFX_IPC_SUBMIT_COMMANDS int32 = 0x204
const GFX_IPC_PRESENT_WINDOW int32 = 0x205
const GFX_IPC_PUSH_EVENT int32 = 0x206
const GFX_IPC_SET_DISPLAY_MODE int32 = 0x208
const GFX_IPC_LIST_WINDOWS int32 = 0x209
const GFX_IPC_FOCUS_WINDOW int32 = 0x20A
const GFX_IPC_SET_WINDOW_FLAGS int32 = 0x20B
const GFX_IPC_GET_DISPLAY_INFO int32 = 0x20C
const GFX_IPC_MOVE_WINDOW int32 = 0x20D
const GFX_IPC_SET_WINDOW_TITLE int32 = 0x20E
const GFX_IPC_GET_WINDOW_TITLE int32 = 0x20F
// Reply the CONSTRAINTS a surface must satisfy for `window_id`; allocates
// nothing. arg0 = window_id, arg1..arg3 reserved (0). The reply carries
// arg1 = stride in bytes, arg2 = required byte size, arg3 = (width << 16)
// | height, all for the window's current content extent.
//
// The client then acquires a transfer buffer of at least that size,
// borrows it to the compositor, and names it with GFX_IPC_ATTACH_SURFACE.
// A resize bumps the window generation, so the spec must be re-read and a
// new surface attached rather than the attached one resized in place --
// a borrowed buffer is never mutated (docs/architecture/12-dma-transfers.md).
//
// This replaced a compositor-side allocation that granted the buffer to
// the caller: a server cannot own a buffer it hands to a client.
const GFX_IPC_GET_SURFACE_SPEC int32 = 0x210
// Register a surface the CLIENT owns and has borrowed to the compositor.
// arg0 = window_id, arg1 = buffer_id, arg2 = borrow_id, arg3 reserved (0).
//
// Three ids are a fixed, non-growing set, so they travel as bare argument
// words rather than a descriptor (skills/wasmos-add-opcode, Step 0).
// Both ids are required and neither is derivable compositor-side:
// xfer_buffer_borrow returns borrow_id to the OWNER, and the two are not
// interchangeable -- xfer_buffer_read/write key on buffer_id, while the
// borrow-side mapping path keys on borrow_id.
//
// Attach registers a surface; GFX_IPC_PRESENT_WINDOW names which attached
// surface is ready. Keeping them separate is what lets a client hold two
// surfaces at once, which both resize and tear-free presentation need.
const GFX_IPC_ATTACH_SURFACE int32 = 0x211
// Withdraw a surface previously attached with GFX_IPC_ATTACH_SURFACE.
// arg0 = window_id, arg1 = buffer_id, arg2..arg3 reserved (0).
//
// The client MUST detach before releasing the buffer. There is no
// unborrow notification, so a release while the compositor still holds
// the borrow leaves it reading a revoked borrow mid-composite; the
// acknowledged detach is that missing handshake. This replaced a call
// that asked the compositor to free a buffer the compositor owned.
const GFX_IPC_DETACH_SURFACE int32 = 0x212
const GFX_IPC_RESP int32 = 0x280
const GFX_IPC_ERROR int32 = 0x2FF

// pci (0xD00..0xDFF)
// Ask what message-signalled interrupt support a PCI function has.
// arg0=bdf ((bus<<8)|(device<<3)|function) arg1..arg3=reserved(0).
// On success: PCI_IPC_RESP, arg0=WASMOS_PCI_MSI_KIND_* (MSIX preferred
// over MSI when both are present), arg1=number of vectors the device
// supports. On failure: PCI_IPC_ERROR, arg1=packed msi domain code.
const PCI_IPC_MSI_QUERY int32 = 0xD00
// Program one MSI/MSI-X table entry of a PCI function with an
// address/data pair the caller obtained from wasmos_msi_alloc, enable the
// capability, and set INTX_DISABLE so the device stops driving its shared
// INTx line.
// arg0=((bdf<<8)|entry) arg1=address_lo arg2=address_hi arg3=data.
// On success: PCI_IPC_RESP, arg0=entry. On failure: PCI_IPC_ERROR,
// arg1=packed msi domain code.
const PCI_IPC_MSI_BIND int32 = 0xD01
// Mask one MSI/MSI-X table entry again. Disables the whole capability
// when the last bound entry of the function is released.
// arg0=((bdf<<8)|entry) arg1..arg3=reserved(0).
// On success: PCI_IPC_RESP, arg0=entry. On failure: PCI_IPC_ERROR,
// arg1=packed msi domain code.
const PCI_IPC_MSI_UNBIND int32 = 0xD02
const PCI_IPC_RESP int32 = 0xD80
const PCI_IPC_ERROR int32 = 0xDFF

// system (0xFF02..0xFF82)
// The system is going down; quiesce and answer WASMOS_IPC_SHUTDOWN_DONE.
// arg0 = reason (0 = halt, 1 = reboot), arg1..arg3 reserved (0).
// Sent by the process manager to every registered driver and service in
// REVERSE spawn order, so a participant still has the services beneath it
// while it quiesces (docs/architecture/15-drivers-and-services.md,
// "Orderly Shutdown Design Direction").
// A participant that does not answer within the deadline is passed over
// and the machine still goes down, which is safe because of what the
// notification exists to do: a filesystem that misses it mounts read-only
// next boot rather than serving inconsistent metadata.
// This subsystem's range is above every other subsystem's because the
// message arrives on the PARTICIPANT's own endpoint, where a
// subsystem-scoped value would collide -- gfx and proc_manager both own
// 0x200. It is the band the kernel's IRQ (0xff00) and MSI (0xff01) events
// already use for the same reason; those two stay hand-written in
// src/drivers/include/wasmos_driver_abi.h and src/kernel/include/irq.h.
const WASMOS_IPC_SHUTDOWN_REQ int32 = 0xFF02
// Sent back to the process manager when a participant has quiesced.
// arg0..arg3 reserved (0). Answering does not mean the participant stops
// running; it means nothing it holds still needs to reach a device.
const WASMOS_IPC_SHUTDOWN_DONE int32 = 0xFF82

// volume (0xE00..0xEFF)
// Ask the volume manager to describe one volume into a buffer the CALLER
// owns. arg0 = the volume's `volume` CLASS INSTANCE, arg1 = buffer_id.
// Answered with VOLUME_IPC_IDENTIFY_RESP.
//
// Same ownership as BLOCK_IPC_IDENTIFY_REQ, and for the same reason: the
// caller acquires the buffer and borrows it to this endpoint with WRITE,
// because the client of a request owns the buffer and the server is a
// transient grantee (architecture/12-dma-transfers.md).
//
// What a caller wants from this is usually `backing_instance`: a volume
// is not something you read from, it is something that tells you which
// `block` device to read from. The volume manager is deliberately not in
// the I/O path.
const VOLUME_IPC_IDENTIFY_REQ int32 = 0xE00
// Record that the sender has mounted a volume, or release that record.
// arg0 = the volume's class instance, arg1 = 1 to claim and 0 to release.
// Answered with VOLUME_IPC_RESP, arg0 = 0.
//
// RECORDS a claim; does not enforce one. The volume manager is not in the
// I/O path, so a tool that does not ask is not stopped -- this is what
// `fsck` and `mkfs` consult before touching a volume that may be mounted,
// and enforcing it would mean standing in the data path for every read to
// prevent a mistake only those two can make.
const VOLUME_IPC_CLAIM_REQ int32 = 0xE01
// arg0 = 0, arg1 = bytes written into the caller's buffer.
const VOLUME_IPC_IDENTIFY_RESP int32 = 0xE80
const VOLUME_IPC_RESP int32 = 0xE81
// arg0 = packed error code.
const VOLUME_IPC_ERROR int32 = 0xEFF
